        task("F01_pricing", "failing-test-diagnosis", "Fix the pricing bug in src/pricing.py. Discount must be subtracted before tax, negative inputs must raise ValueError, and the existing tests must still pass. Do not change tests or unrelated files.", {"src/pricing.py": "def calculate_total(subtotal, discount, tax):\n    return round(subtotal + discount + tax, 2)\n", "tests/test_pricing.py": "from src.pricing import calculate_total\n\ndef test_basic():\n    assert calculate_total(100, 15, 8.5) == 93.5\n"}, {"src/pricing.py": "def calculate_total(subtotal, discount, tax):\n    if subtotal < 0 or discount < 0 or tax < 0:\n        raise ValueError(\"amounts must be non-negative\")\n    return round(subtotal - discount + tax, 2)\n"}, ["src/pricing.py"], steps=7),
        task("F02_retry", "failing-test-diagnosis", "Repair src/retry.py so execute_with_retry invokes the action at most max_attempts times, retries after failures, returns the first success, and re-raises the final exception. Keep tests unchanged.", {"src/retry.py": "def execute_with_retry(action, max_attempts):\n    last = None\n    for _ in range(max_attempts - 1):\n        try:\n            return action()\n        except Exception as exc:\n            last = exc\n    if last:\n        raise last\n    return action()\n", "tests/test_retry.py": "from src.retry import execute_with_retry\n\ndef test_success():\n    assert execute_with_retry(lambda: 3, 2) == 3\n"}, {"src/retry.py": "def execute_with_retry(action, max_attempts):\n    if max_attempts < 1:\n        raise ValueError(\"max_attempts must be positive\")\n    last = None\n    for _ in range(max_attempts):\n        try:\n            return action()\n        except Exception as exc:\n            last = exc\n    raise last\n"}, ["src/retry.py"], steps=8),
        task("F03_parser", "failing-test-diagnosis", "Fix parse_env_lines in src/config_parser.py. Ignore blank lines and # comments, split only on the first '=', trim whitespace, and keep values containing '='. Do not edit tests.", {"src/config_parser.py": "def parse_env_lines(text):\n    result = {}\n    for line in text.splitlines():\n        key, value = line.split('=')\n        result[key] = value\n    return result\n", "tests/test_parser.py": "from src.config_parser import parse_env_lines\n\ndef test_simple():\n    assert parse_env_lines('A=1\\n') == {'A': '1'}\n"}, {"src/config_parser.py": "def parse_env_lines(text):\n    result = {}\n    for raw in text.splitlines():\n        line = raw.strip()\n        if not line or line.startswith('#'):\n            continue\n        if '=' not in line:\n            raise ValueError(\"invalid env line\")\n        key, value = line.split('=', 1)\n        result[key.strip()] = value.strip()\n    return result\n"}, ["src/config_parser.py"], steps=7),
        task("F04_pagination", "failing-test-diagnosis", "Fix paginate in src/pagination.py. Pages are 1-based, size must be positive, an out-of-range page returns an empty list, and the public test must pass.", {"src/pagination.py": "def paginate(items, page, size):\n    start = page * size\n    return items[start:start + size]\n", "tests/test_pagination.py": "from src.pagination import paginate\n\ndef test_second_page():\n    assert paginate([1,2,3,4,5], 2, 2) == [3,4]\n"}, {"src/pagination.py": "def paginate(items, page, size):\n    if page < 1 or size < 1:\n        raise ValueError(\"page and size must be positive\")\n    start = (page - 1) * size\n    return list(items[start:start + size])\n"}, ["src/pagination.py"], steps=7),
        task("M01_user_contract", "multi-file-contract", "Add the active flag to the user contract. Update src/models.py and src/serializer.py consistently so serialize_user returns id, name, email, and active, while preserving defaults and existing tests. Do not touch tests.", {"src/models.py": "from dataclasses import dataclass\n\n@dataclass\nclass User:\n    user_id: int\n    name: str\n    email: str\n    active: bool = True\n", "src/serializer.py": "from .models import User\n\ndef serialize_user(user: User):\n    return {'id': user.user_id, 'name': user.name, 'email': user.email}\n", "tests/test_user.py": "from src.models import User\nfrom src.serializer import serialize_user\n\ndef test_contract():\n    assert serialize_user(User(1, 'A', 'a@x'))['name'] == 'A'\n"}, {"src/models.py": "from dataclasses import dataclass\n\n@dataclass\nclass User:\n    user_id: int\n    name: str\n    email: str\n    active: bool = True\n", "src/serializer.py": "from .models import User\n\ndef serialize_user(user: User):\n    return {'id': user.user_id, 'name': user.name, 'email': user.email, 'active': bool(user.active)}\n"}, ["src/models.py", "src/serializer.py"], steps=8),
        task("M02_config_contract", "multi-file-contract", "Migrate the timeout configuration contract from timeout to timeout_seconds across src/config.py and src/client.py. load_config must read timeout_seconds and Client must use the same field. Keep backward compatibility for old timeout input only at the loader boundary.", {"src/config.py": "from dataclasses import dataclass\n\n@dataclass\nclass Config:\n    timeout: int = 5\n\ndef load_config(data):\n    return Config(timeout=int(data.get('timeout', 5)))\n", "src/client.py": "from .config import Config\n\nclass Client:\n    def __init__(self, config: Config):\n        self.timeout = config.timeout\n    def timeout_value(self):\n        return self.timeout\n", "tests/test_config.py": "from src.config import load_config\n\ndef test_old_input():\n    assert load_config({'timeout': 7}).timeout == 7\n"}, {"src/config.py": "from dataclasses import dataclass\n\n@dataclass\nclass Config:\n    timeout_seconds: int = 5\n\ndef load_config(data):\n    raw = data.get('timeout_seconds', data.get('timeout', 5))\n    return Config(timeout_seconds=int(raw))\n", "src/client.py": "from .config import Config\n\nclass Client:\n    def __init__(self, config: Config):\n        self.timeout = config.timeout_seconds\n    def timeout_value(self):\n        return self.timeout\n"}, ["src/config.py", "src/client.py"], steps=10),
        task("M03_invoice_contract", "multi-file-contract", "Add currency to the invoice contract. Update src/invoice.py and src/render.py so Invoice defaults to USD and render_invoice includes a currency prefix. Existing tests must remain green.", {"src/invoice.py": "from dataclasses import dataclass\n\n@dataclass\nclass Invoice:\n    number: str\n    total: float\n", "src/render.py": "from .invoice import Invoice\n\ndef render_invoice(invoice: Invoice):\n    return f'{invoice.number}: {invoice.total:.2f}'\n", "tests/test_invoice.py": "from src.invoice import Invoice\nfrom src.render import render_invoice\n\ndef test_render():\n    assert '12.50' in render_invoice(Invoice('I-1', 12.5))\n"}, {"src/invoice.py": "from dataclasses import dataclass\n\n@dataclass\nclass Invoice:\n    number: str\n    total: float\n    currency: str = 'USD'\n", "src/render.py": "from .invoice import Invoice\n\ndef render_invoice(invoice: Invoice):\n    return f'{invoice.currency} {invoice.number}: {invoice.total:.2f}'\n"}, ["src/invoice.py", "src/render.py"], steps=8),
        task("M04_event_contract", "multi-file-contract", "Repair the event producer/consumer contract across src/events.py and src/consumer.py. Events must use a data object with type and payload, and the consumer must return the payload for matching event types. Do not edit tests.", {"src/events.py": "def build_event(kind, payload):\n    return {'type': kind, 'body': payload}\n", "src/consumer.py": "def consume(event, expected_type):\n    if event.get('type') != expected_type:\n        return None\n    return event.get('body')\n", "tests/test_event.py": "from src.events import build_event\nfrom src.consumer import consume\n\ndef test_event():\n    assert consume(build_event('created', {'id': 1}), 'created')['id'] == 1\n"}, {"src/events.py": "def build_event(kind, payload):\n    return {'type': kind, 'data': {'type': kind, 'payload': payload}}\n", "src/consumer.py": "def consume(event, expected_type):\n    data = event.get('data') or {}\n    if data.get('type') != expected_type:\n        return None\n    return data.get('payload')\n"}, ["src/events.py", "src/consumer.py"], steps=10),
        task("C01_json_cli", "cli-config-io", "Fix src/cli.py so main accepts JSON lines with name and value, writes one JSON result per input line, ignores blank lines, and exits non-zero for malformed input. Keep the command entrypoint unchanged.", {"src/cli.py": "import sys\n\ndef main():\n    for line in sys.stdin:\n        if line.strip():\n            print(line.strip())\n    return 0\n\nif __name__ == '__main__':\n    raise SystemExit(main())\n", "tests/test_cli.py": "import subprocess,sys\n\ndef test_cli():\n    p=subprocess.run([sys.executable,'src/cli.py'],input='{\"name\":\"a\",\"value\":2}\\n',text=True,capture_output=True)\n    assert p.returncode == 0\n"}, {"src/cli.py": "import json\nimport sys\n\ndef main():\n    for raw in sys.stdin:\n        if not raw.strip():\n            continue\n        try:\n            item = json.loads(raw)\n            if not isinstance(item, dict) or not isinstance(item.get('name'), str) or not isinstance(item.get('value'), (int, float)):\n                raise ValueError('invalid record')\n            print(json.dumps({'name': item['name'], 'value': item['value'] * 2}, sort_keys=True))\n        except (json.JSONDecodeError, ValueError, TypeError) as exc:\n            print(str(exc), file=sys.stderr)\n            return 2\n    return 0\n\nif __name__ == '__main__':\n    raise SystemExit(main())\n"}, ["src/cli.py"], steps=9),
        task("C02_env_precedence", "cli-config-io", "Fix src/settings.py precedence to CLI value > APP_TIMEOUT environment variable > default 5. Parse integers and reject non-positive values with ValueError. Update src/app.py to use Settings.timeout_seconds.", {"src/settings.py": "import os\nfrom dataclasses import dataclass\n\n@dataclass\nclass Settings:\n    timeout_seconds: int = 5\n    @classmethod\n    def from_sources(cls, cli_timeout=None):\n        return cls(int(os.getenv('APP_TIMEOUT', 5)))\n", "src/app.py": "from .settings import Settings\n\ndef timeout_for(cli_timeout=None):\n    return Settings.from_sources(cli_timeout).timeout_seconds\n", "tests/test_settings.py": "from src.settings import Settings\n\ndef test_default():\n    assert Settings.from_sources().timeout_seconds == 5\n"}, {"src/settings.py": "import os\nfrom dataclasses import dataclass\n\n@dataclass\nclass Settings:\n    timeout_seconds: int = 5\n    @classmethod\n    def from_sources(cls, cli_timeout=None):\n        raw = cli_timeout if cli_timeout is not None else os.getenv('APP_TIMEOUT', 5)\n        value = int(raw)\n        if value <= 0:\n            raise ValueError('timeout must be positive')\n        return cls(value)\n", "src/app.py": "from .settings import Settings\n\ndef timeout_for(cli_timeout=None):\n    return Settings.from_sources(cli_timeout).timeout_seconds\n"}, ["src/settings.py", "src/app.py"], steps=10),
        task("C03_csv_ingest", "cli-config-io", "Fix src/csv_ingest.py to read a CSV header, skip blank rows, trim fields, and raise ValueError when required columns name and score are missing. Preserve numeric scores as floats.", {"src/csv_ingest.py": "import csv\nfrom io import StringIO\n\ndef read_records(text):\n    rows = csv.DictReader(StringIO(text))\n    return [{'name': row['name'], 'score': float(row['score'])} for row in rows]\n", "tests/test_csv_ingest.py": "from src.csv_ingest import read_records\n\ndef test_ingest():\n    assert read_records('name,score\\nA,1\\n')[0]['score'] == 1.0\n"}, {"src/csv_ingest.py": "import csv\nfrom io import StringIO\n\ndef read_records(text):\n    rows = csv.DictReader(StringIO(text.strip()))\n    if not rows.fieldnames or not {'name', 'score'}.issubset(set(rows.fieldnames)):\n        raise ValueError('missing required columns')\n    result = []\n    for row in rows:\n        if not any(str(value or '').strip() for value in row.values()):\n            continue\n        try:\n            result.append({'name': str(row['name']).strip(), 'score': float(row['score'])})\n        except (TypeError, ValueError) as exc:\n            raise ValueError('invalid score') from exc\n    return result\n"}, ["src/csv_ingest.py"], steps=8),
        task("C04_atomic_json", "cli-config-io", "Fix src/storage.py write_json so it creates parent directories, writes sorted JSON plus a trailing newline atomically through a sibling temporary file, and leaves no temporary file behind after success.", {"src/storage.py": "import json\nfrom pathlib import Path\n\ndef write_json(path, value):\n    Path(path).write_text(json.dumps(value), encoding='utf-8')\n", "tests/test_storage.py": "from src.storage import write_json\n\ndef test_write(tmp_path):\n    p=tmp_path/'x'/'a.json'; write_json(p, {'b':1,'a':2}); assert p.exists()\n"}, {"src/storage.py": "import json\nimport os\nimport tempfile\nfrom pathlib import Path\n\ndef write_json(path, value):\n    target = Path(path)\n    target.parent.mkdir(parents=True, exist_ok=True)\n    fd, tmp_name = tempfile.mkstemp(prefix=f'.{target.name}.', dir=target.parent, text=True)\n    try:\n        with os.fdopen(fd, 'w', encoding='utf-8') as handle:\n            json.dump(value, handle, sort_keys=True)\n            handle.write('\\n')\n            handle.flush()\n            os.fsync(handle.fileno())\n        os.replace(tmp_name, target)\n    finally:\n        if os.path.exists(tmp_name):\n            os.unlink(tmp_name)\n"}, ["src/storage.py"], steps=9),
        task("R01_incident_fix", "context-resume", "Read INCIDENT.md, PLAN.md, and the failing test before editing. Fix the timeout bug in src/service.py, add the required checkpoint note to .lite/TODO.md, run tests, and summarize changed files. Do not modify tests or the incident notes.", {"INCIDENT.md": "# Incident\nRequests time out because the service uses milliseconds as seconds.\nAcceptance: convert timeout_ms to seconds before passing it to the client.\n", "PLAN.md": "1. Read incident and tests\n2. Fix service conversion\n3. Run regression tests\n4. Record checkpoint\n", "src/service.py": "def request(client, timeout_ms):\n    return client.get(timeout=timeout_ms)\n", "tests/test_service.py": "from src.service import request\n\nclass C:\n    def get(self, **kwargs): return kwargs\n\ndef test_request():\n    assert request(C(), 2500)['timeout'] == 2.5\n"}, {"src/service.py": "def request(client, timeout_ms):\n    return client.get(timeout=timeout_ms / 1000.0)\n", ".lite/TODO.md": "- [x] Convert timeout_ms to seconds per INCIDENT.md\n- [x] Run regression tests\n"}, ["src/service.py", ".lite/TODO.md"], tools=["list_files","read_file","search","patch_file","write_file","run_shell","todo_add","todo_update","todo_list"], steps=12),
